import type { On, PluginOptions, Register, SessionMessage, TurnCompleteInput } from 'claude-code';

const DEFAULTS = {
  vaultPath: '~/vault',
  threshold: 0.6,
  minAnswerChars: 200,
  model: 'jev-latest',
};

const SYSTEM_ONE_URL = 'https://api.typesafe.ai/v1/systemone';
const MAX_TEXT_CHARS = 4000;
const MAX_TOPICS = 20;

type NoulAnswer = { noul: number };
type ChoiceAnswer = { choice: string; confidence: number };
type JevAnswer = NoulAnswer | ChoiceAnswer;
type JevQuestions = Record<string, { type: 'noul' | 'choice'; instructions: string; criteria?: Record<string, string | null> }>;

interface Config {
  apiKey?: string;
  vaultPath: string;
  threshold: number;
  minAnswerChars: number;
  model: string;
}

function optionNumber(options: PluginOptions, key: string, fallback: number): number {
  const value = options[key];
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

function optionString(options: PluginOptions, key: string, fallback: string): string {
  const value = options[key];
  return typeof value === 'string' && value.length > 0 ? value : fallback;
}

function resolveConfig(options: PluginOptions): Config {
  const apiKey = optionString(options, 'apiKey', '');
  return {
    apiKey: apiKey || undefined,
    vaultPath: optionString(options, 'vaultPath', DEFAULTS.vaultPath),
    threshold: optionNumber(options, 'threshold', DEFAULTS.threshold),
    minAnswerChars: optionNumber(options, 'minAnswerChars', DEFAULTS.minAnswerChars),
    model: optionString(options, 'model', DEFAULTS.model),
  };
}

function expandHome(path: string, home: string): string {
  return path === '~' || path.startsWith('~/') ? home + path.slice(1) : path;
}

function truncate(text: string, max: number): string {
  return text.length <= max ? text : `${text.slice(0, max)}\n[...truncated...]`;
}

/**
 * Deterministic, local redaction applied ONLY to what leaves the machine for
 * Jev — the gate/route questions never need the real value, just that a
 * secret-shaped thing is there. The unredacted text still goes into
 * vault/raw/ untouched; that's the whole point of the vault.
 */
function scrubSecrets(text: string): string {
  return text
    // key=value / key: value credential assignments (api key, token, password, secret, community string, bearer)
    .replace(
      /\b((?:api[_-]?key|access[_-]?key|secret[_-]?key|client[_-]?secret|auth[_-]?token|bearer|password|passwd|pwd|community(?:[_-]?string)?)\s*[:=]\s*)(\S+)/gi,
      '$1[REDACTED]',
    )
    // PEM-style private key / certificate blocks
    .replace(/-----BEGIN [^-]+-----[\s\S]*?-----END [^-]+-----/g, '[REDACTED PEM BLOCK]')
    // AWS-style access key ids
    .replace(/\bAKIA[0-9A-Z]{16}\b/g, '[REDACTED_AWS_KEY]')
    // long bearer/JWT-looking tokens standing alone
    .replace(/\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g, '[REDACTED_JWT]')
    // MAC addresses
    .replace(/\b([0-9a-fA-F]{2}[:-]){5}[0-9a-fA-F]{2}\b/g, '[MAC]')
    // IPv4 addresses (network inventory is the main thing this vault handles)
    .replace(/\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b/g, '[IP]');
}

/** Pulls `[[page-slug]]` wikilinks out of INDEX.md as candidate topic buckets. */
function extractTopics(indexMd: string): string[] {
  const found = new Set<string>();
  for (const match of indexMd.matchAll(/\[\[([a-z0-9-]+)\]\]/g)) {
    found.add(match[1]!);
    if (found.size >= MAX_TOPICS) break;
  }
  return [...found];
}

function lastUserText(messages: readonly SessionMessage[]): string {
  for (let i = messages.length - 1; i >= 0; i--) {
    const message = messages[i]!;
    if (message.role === 'user' && message.text.trim().length > 0) return message.text;
  }
  return '';
}

async function askJev(
  fetchFn: (url: string, init: { method: string; headers: Record<string, string>; body: string }) => Promise<{ status: number; ok: boolean; text: string }>,
  config: Config,
  state: unknown,
  questions: JevQuestions,
): Promise<Record<string, JevAnswer>> {
  const response = await fetchFn(SYSTEM_ONE_URL, {
    method: 'POST',
    headers: { authorization: `Bearer ${config.apiKey}`, 'content-type': 'application/json' },
    body: JSON.stringify({ model: config.model, state, questions }),
  });
  if (!response.ok) throw new Error(`Jev request failed (${response.status}): ${response.text.slice(0, 200)}`);
  const parsed = JSON.parse(response.text) as { answers?: Record<string, JevAnswer> };
  if (!parsed.answers) throw new Error('Jev response is missing answers');
  return parsed.answers;
}

function slugifyTitle(text: string, maxWords: number): string {
  return text
    .split(/\s+/)
    .slice(0, maxWords)
    .join(' ')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60);
}

export const register: Register = (on: On, options: PluginOptions) => {
  const configured = resolveConfig(options);

  on('turn.complete', async ($, event: TurnCompleteInput, next) => {
    if (event.agentId) return next(event); // subagent turns aren't the user's own work log
    if (event.reason !== 'answer') return next(event);
    if (event.answer.length < configured.minAnswerChars) return next(event);

    try {
      const apiKey = configured.apiKey ?? (await $.env.get('TYPESAFE_API_KEY'));
      if (!apiKey) {
        $.ui.log('jev-vault-gate: TYPESAFE_API_KEY not configured, skipping capture check');
        return next(event);
      }
      const config = { ...configured, apiKey };
      const home = (await $.env.get('HOME')) ?? '';
      const vaultPath = expandHome(config.vaultPath, home);

      let topics: string[] = [];
      try {
        const indexMd = await $.fs.read(`${vaultPath}/INDEX.md`);
        topics = extractTopics(indexMd);
      } catch {
        // no INDEX.md yet, or vault path not set up; capture still works without topic routing
      }

      const messages = await $.session.messages();
      const userText = truncate(lastUserText(messages), MAX_TEXT_CHARS);
      const assistantText = truncate(event.answer, MAX_TEXT_CHARS);

      const state = {
        context:
          'One turn of a technical work session: a user message and the assistant\'s reply, with ' +
          'credential- and address-shaped values already redacted before reaching you — judge the ' +
          'structure and topic, not the exact values. Judge whether it holds durable knowledge ' +
          'worth keeping in a personal engineering vault (facts: inventory, configs, architecture; ' +
          'lessons: methods, root causes, gotchas, fixes) that would still be useful weeks or ' +
          'months later. Most turns are ordinary back-and-forth, task chatter, or acknowledgements ' +
          'and do not qualify.',
        user: scrubSecrets(userText),
        assistant: scrubSecrets(assistantText),
      };

      const questions: JevQuestions = {
        worthy: {
          type: 'noul',
          instructions:
            'This turn holds durable knowledge worth saving to the vault, per the context above. ' +
            'Most turns do not; only answer high when the content itself shows a fact or lesson, ' +
            'not because the turn is long or technical-sounding.',
        },
      };
      if (topics.length > 0) {
        const criteria: Record<string, string | null> = { new_topic: 'None of the existing pages fit this content.' };
        for (const topic of topics) criteria[topic] = null;
        questions['topic'] = {
          type: 'choice',
          instructions: 'Which existing vault page this turn\'s content most belongs under, or new_topic.',
          criteria,
        };
      }

      const answers = await askJev(
        async (url, init) => {
          const response = await $.http.fetch(url, init);
          return { status: response.status, ok: response.ok, text: response.text };
        },
        config,
        state,
        questions,
      );

      const worthy = answers['worthy'] as NoulAnswer | undefined;
      const score = worthy?.noul ?? 0;
      if (!Number.isFinite(score) || score < config.threshold) return next(event);

      const topicAnswer = answers['topic'] as ChoiceAnswer | undefined;
      const date = new Date().toISOString().slice(0, 10);
      const slug = slugifyTitle(userText || assistantText, 8) || event.turnId.slice(0, 8);
      const path = `${vaultPath}/raw/${date}-${slug}.md`;
      if (await $.fs.exists(path)) return next(event); // already captured (hot reload re-run, etc.)

      const header = [
        `<!-- captured by jev-vault-gate: turn ${event.turnId}, score ${score.toFixed(2)}` +
          (topicAnswer ? `, topic ${topicAnswer.choice} (${topicAnswer.confidence.toFixed(2)})` : '') +
          ' -->',
        `# ${date} ${slug.replace(/-/g, ' ')}`,
        '',
        '## User',
        '',
        userText,
        '',
        '## Assistant',
        '',
        assistantText,
        '',
      ].join('\n');
      await $.fs.write(path, header);

      const pending = Number((await $.store.get('pendingCount')) ?? 0) + 1;
      await $.store.set('pendingCount', pending);
      $.ui.log(`jev-vault-gate: captured to ${path} (score ${score.toFixed(2)})`);
    } catch (error) {
      $.ui.log(`jev-vault-gate: capture check skipped (${error instanceof Error ? error.message : String(error)})`);
    }
    return next(event);
  });

  on('classic.UserPromptSubmit', async ($, e, next) => {
    const result = await next(e);
    const pending = Number((await $.store.get('pendingCount')) ?? 0);
    if (pending === 0) return result;
    await $.store.set('pendingCount', 0);
    const note = `jev-vault-gate: ${pending} new vault raw file(s) captured since last prompt — run /compile when convenient.`;
    return { ...result, additionalContext: [...(result.additionalContext ?? []), note] };
  });
};

