{
  "name": "jev-vault-gate",
  "version": "0.3.0",
  "description": "Uses Jev to spot durable knowledge in a turn and auto-capture it into ~/vault/raw/ for /compile.",
  "license": "MIT",
  "userConfig": {
    "apiKey": {
      "type": "string",
      "title": "TypeSafe API key",
      "description": "TypeSafe API key. Leave unset to use TYPESAFE_API_KEY.",
      "sensitive": true
    },
    "vaultPath": {
      "type": "string",
      "title": "Vault path",
      "description": "Absolute path to the vault (must contain INDEX.md and a raw/ directory). Defaults to ~/vault.",
      "default": "~/vault"
    },
    "threshold": {
      "type": "number",
      "title": "Capture threshold",
      "description": "Minimum Jev probability that a turn holds durable knowledge before it's captured.",
      "default": 0.6
    },
    "minAnswerChars": {
      "type": "number",
      "title": "Minimum answer length",
      "description": "Assistant answers shorter than this are never checked (too short to hold durable knowledge).",
      "default": 200
    },
    "model": {
      "type": "string",
      "title": "Jev model",
      "description": "TypeSafe Jev model name.",
      "default": "jev-latest"
    }
  }
}
